function vNearest(sites, x, y){ var bi=-1, bd=Infinity; for(var i=0;i<sites.length;i++){ var dx=sites[i].x-x, dy=sites[i].y-y, d=dx*dx+dy*dy; if(d<bd){bd=d;bi=i;} } return bi; }
function vGrid(sites, w, h, step){ var g=[]; for(var y=0;y<h;y+=step){ var row=[]; for(var x=0;x<w;x+=step){ row.push(vNearest(sites,x,y)); } g.push(row); } return g; }
function vColors(n){ var cs=[]; for(var i=0;i<n;i++){ var h=Math.round(i*360/Math.max(1,n)); cs.push('hsl('+h+',72%,62%)'); } return cs; }
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { vNearest:vNearest, vGrid:vGrid, vColors:vColors };
}
if (typeof window !== 'undefined') {
  window.VoronoiForgePure = { vNearest:vNearest, vGrid:vGrid, vColors:vColors };
}
